// Mirrors src/csv.js of the CLI example: required-column checks,
// per-row validation, slugified job names, optional row limit.
const REQUIRED = ['first_name','product_name','product_tagline','product_image','discount_label','coupon_code','cta_url'];
const cfg = $('Campaign Config').first().json;
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) throw new Error('CSV contains no data rows');

const missing = REQUIRED.filter((c) => !(c in rows[0]));
if (missing.length) {
  throw new Error(`CSV is missing required column(s): ${missing.join(', ')}. Expected header: ${REQUIRED.join(',')}`);
}

const slugify = (v) => String(v).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'row';
// note: the Code sandbox has no URL global - keep this a regex
const isHttpUrl = (v) => /^https?:\/\//i.test(String(v).trim());

const items = [];
const rowErrors = [];
rows.forEach((record, index) => {
  const row = index + 1; // 1-based CSV data row (header excluded)
  const problems = [];
  for (const c of REQUIRED) if (!record[c]) problems.push(`"${c}" is empty`);
  if (record.product_image && !isHttpUrl(record.product_image)) problems.push('"product_image" must be an http(s) URL');
  if (problems.length) { rowErrors.push({ row, error: problems.join('; ') }); return; }
  items.push({
    row,
    name: `offer-${slugify(record.first_name)}-r${row}`,
    variables: {
      firstName: record.first_name,
      productName: record.product_name,
      productMeta: record.product_tagline,
      productImage: record.product_image,
      discountLabel: record.discount_label,
      couponCode: record.coupon_code,
      ctaUrl: record.cta_url,
    },
  });
});

if (items.length === 0) throw new Error('No valid rows in the CSV - nothing to render. Reasons: ' + JSON.stringify(rowErrors.slice(0, 5)));
const limit = Number(cfg.rowLimit) || 0;
const limited = limit > 0 ? items.slice(0, limit) : items;
// rowErrors ride on the first item so the manifest can report skipped rows
return limited.map((it, i) => ({ json: i === 0 ? { ...it, rowErrors } : it }));

// Per-row validation report + total credit estimate. No credits spent.
const items = $('Build bulk items').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
let creditsRequired = 0;
let invalid = 0;
const rows = results.map((r, i) => {
  const item = items[i] || {};
  if (r.error || r.valid === false) {
    invalid += 1;
    const message = typeof r.error === 'string' ? r.error : (r.error && r.error.message) || r.message || 'invalid';
    return { csv_row: item.row, name: item.name, valid: false, error: message };
  }
  creditsRequired += r.creditsRequired || 0;
  return { csv_row: item.row, name: item.name, valid: true, credits: r.creditsRequired, layoutWarnings: (r.warnings || []).length };
});
return [{ json: {
  dryRun: true,
  videos: results.length - invalid,
  invalidRows: invalid,
  creditsRequired,
  note: 'No credits were spent. Set dryRun=false in Campaign Config to render.',
  rows,
} }];

// One envelope per batch (up to batchSize items) - same merge semantics as
// the CLI: item variables > batch variables > template defaults.
const cfg = $('Campaign Config').first().json;
const items = $input.all().map((i) => i.json);
return [{ json: {
  request: {
    payload: $('Fetch template.json').first().json,
    variables: $('Fetch campaign.json').first().json,
    items: items.map(({ variables, name }) => ({ variables, name })),
    name: cfg.batchName,
  },
} }];

// The loop's done-output delivers one 202 response per batch, in batch order.
// Re-derive each batch's rows by slicing the same item list the loop consumed,
// then map every queued job to its CSV row via the batch-relative jobs[].index.
const cfg = $('Campaign Config').first().json;
const batchSize = Math.max(1, Number(cfg.batchSize) || 100);
const allItems = $('Build bulk items').all().map((i) => i.json);
const submits = $input.all().map((i) => i.json);

const jobsMeta = [];
const rejected = [];
const bulks = [];
submits.forEach((submit, b) => {
  const batch = allItems.slice(b * batchSize, (b + 1) * batchSize);
  for (const job of submit.jobs || []) {
    const item = batch[job.index] || {};
    jobsMeta.push({ jobId: job.jobId, row: item.row, name: item.name });
  }
  for (const e of submit.errors || submit.itemErrors || []) {
    const idx = e.item != null ? e.item : e.index;
    const item = typeof idx === 'number' ? batch[idx] : undefined;
    const details = (e.errors || e.details || []).map((d) => `${d.field}: ${d.message}`).join('; ');
    rejected.push({ csv_row: item ? item.row : null, name: item ? item.name : `item-${idx}`, error: details || e.error || e.message || 'invalid' });
  }
  bulks.push({ bulkId: submit.bulkId, creditsReserved: submit.creditsReserved || 0, totalJobs: submit.totalJobs || 0 });
});

const aggregate = {
  jobsMeta,
  rejected,
  rowErrors: $('Build bulk items').first().json.rowErrors || [],
  creditsReservedTotal: bulks.reduce((a, x) => a + x.creditsReserved, 0),
  totalJobs: bulks.reduce((a, x) => a + x.totalJobs, 0),
  bulkIds: bulks.map((x) => x.bulkId),
};
// One output item per bulkId (the poll loop fetches each); aggregate rides on the first.
return bulks.map((x, i) => ({ json: i === 0 ? { ...x, aggregate } : x }));

// Aggregate progress across every batch. Input order always mirrors Collect
// submissions' output order, so bulkIds can be re-attached by position.
const bulkIds = $('Collect submissions').all().map((i) => i.json.bulkId);
const responses = $input.all().map((i) => i.json);
const counts = { completed: 0, failed: 0, pending: 0 };
for (const r of responses) {
  counts.completed += r.bulk.counts.completed;
  counts.failed += r.bulk.counts.failed;
  counts.pending += r.bulk.counts.pending;
}
const done = counts.pending === 0;
return responses.map((r, i) => ({ json: { bulkId: bulkIds[i], done, counts, response: r } }));

// Loop back to Wait unless we have polled for longer than timeoutMinutes.
const cfg = $('Campaign Config').first().json;
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 30) * 60) / Math.max(2, Number(cfg.pollSeconds || 10)));
if ($runIndex >= maxPolls) {
  const first = $input.first().json;
  throw new Error(`Timed out after ${cfg.timeoutMinutes} min with ${first.counts.pending} job(s) still rendering. Check later: GET ${cfg.apiUrl}/api/render/bulk/${first.bulkId}`);
}
return $input.all();

// Join poll results to CSV rows BY JOB ID (job name is null until completed),
// plus items the API rejected at submit and rows skipped locally.
const meta = $('Collect submissions').first().json.aggregate;
const byJobId = new Map(meta.jobsMeta.map((m) => [m.jobId, m]));
const rows = [];
for (const item of $input.all()) {
  for (const job of item.json.response.jobs || []) {
    const m = byJobId.get(job.id) || {};
    rows.push({
      csv_row: m.row != null ? m.row : null,
      name: job.name || m.name || job.id,
      status: job.status,
      video_url: job.outputUrl || '',
      thumbnail_url: job.thumbnailUrl || '',
      credits: job.creditsConsumed != null ? job.creditsConsumed : null,
      error: job.errorMessage || '',
    });
  }
}
for (const e of meta.rejected || []) {
  rows.push({ csv_row: e.csv_row, name: e.name, status: 'rejected', video_url: '', thumbnail_url: '', credits: null, error: e.error });
}
for (const e of meta.rowErrors || []) {
  rows.push({ csv_row: e.row, name: '', status: 'skipped', video_url: '', thumbnail_url: '', credits: null, error: e.error });
}
rows.sort((a, b) => ((a.csv_row != null ? a.csv_row : 1e9) - (b.csv_row != null ? b.csv_row : 1e9)));
return rows.map((r) => ({ json: r }));

const manifest = $('Build manifest').all().map((i) => i.json);
const meta = $('Collect submissions').first().json.aggregate;
const cfg = $('Campaign Config').first().json;
const rendered = manifest.filter((r) => r.status === 'completed');
const problems = manifest.filter((r) => r.status !== 'completed');
return [{ json: {
  rendered: rendered.length,
  failedOrSkipped: problems.length,
  creditsReserved: meta.creditsReservedTotal,
  bulkIds: meta.bulkIds,
  savedTo: cfg.saveToDisk ? cfg.outDir : '(saveToDisk=false - videos stay on the CDN, URLs below)',
  videos: rendered.map((r) => ({ name: r.name, url: r.video_url })),
  problems,
} }];
